import sys;sys.path.insert(0,'/mnt/c/WSL/davita/translations/yfr4')
from lib import *
FVG="Portions de fruits et légumes"
def fv(n): return f"{FVG}§{FVG} par portion : {n}"
M="Pour la marinade§";D="Pour la vinaigrette§"
recs=[
R(7940182,"Sauce au pain","Un grand classique, parfait avec un rôti.","8","92 g",
["1 oignon moyen, épluché","10 clous de girofle","600 ml de lait entier","1 feuille de laurier","8 grains de poivre","10 g de matière grasse tartinable végétale","125 g de chapelure fraîche de pain complet"],
["Piquez l'oignon de clous de girofle et placez-le dans une casserole avec le lait, le laurier et les grains de poivre.","Portez à frémissement, puis retirez du feu et laissez infuser 2 heures pour que les saveurs se développent.","Retirez du lait l'oignon, le laurier et les grains de poivre avant d'ajouter la matière grasse et la chapelure.","Faites cuire de nouveau à feu très doux pendant environ 20 minutes, jusqu'à épaississement."],
["Essayez d'ajouter de l'ail écrasé et du persil frais haché pour obtenir une savoureuse sauce au pain à l'ail.","Instructions de congélation : congelez en portions, puis décongelez et servez tiède.",fv(0)]),
R(7941754,"Muesli Bircher","Inventé il y a plus d'un siècle par le médecin suisse Maximilian Bircher-Benner dans sa clinique de Zurich. Il est traditionnellement laissé reposer toute la nuit pour ramollir les flocons d'avoine.","1","330 g",
["30 g de flocons d'avoine","1 c. à café d'édulcorant en grains (facultatif)","50 ml d'eau","50 ml de lait demi-écrémé","1 pomme non épluchée, râpée","1 c. à soupe de yaourt nature non sucré","10 g de pistaches hachées","2 fraises"],
["Ajoutez l'édulcorant aux flocons d'avoine, le cas échéant, puis laissez-les tremper dans l'eau et le lait au moins 45 minutes, ou toute la nuit au réfrigérateur.","Incorporez la pomme aux flocons d'avoine, puis garnissez de yaourt, de fraises et de fruits à coque pour servir."],
["Ce petit-déjeuner est très modulable : vous pouvez utiliser pratiquement n'importe quels fruits et fruits à coque. Essayez avec des poires et des myrtilles séchées, garni de noisettes ou de noix.","Utilisez des alternatives végétales au lait et au yaourt pour une délicieuse version végétalienne.","Essayez d'ajouter de la cannelle ou un peu de gingembre pour relever le goût.","Utilisez des flocons d'avoine sans gluten pour une version sans gluten.",fv(1)]),
R(7942789,"Écrasé de fruits rouges d'été","Un dessert frais et savoureux, parfait pour un repas de famille ou un dîner entre amis.","2","212 g",
["200 g de fruits rouges d'été mélangés surgelés, décongelés","1 pot de 200 g de fromage frais quasiment sans matières grasses","Édulcorant sans sucre, selon le goût","25 g de biscuits amaretti, légèrement écrasés (facultatif)"],
["Mélangez délicatement tous les ingrédients et répartissez-les à la cuillère dans des verres de service. Parsemez de biscuits écrasés si vous le souhaitez."],
["Si vous n'avez pas d'amaretti, vous pouvez utiliser des sablés ou des biscuits au gingembre.","Les informations nutritionnelles indiquées incluent les biscuits, mais ceux-ci sont facultatifs.","Pour une version végétalienne, utilisez un yaourt au soja à la place du fromage frais.",fv(1)]),
R(7943784,"Chow mein de légumes","Chow mein signifie simplement « nouilles sautées ». Ce plat rapide et facile est savoureux, rassasiant, économique et nutritif.","4","338 g",
["200 g de nouilles aux œufs sèches","3 c. à café d'huile de colza","1 oignon, finement émincé","1 poivron rouge, émincé","125 g de champignons shiitake, émincés","2 gousses d'ail, écrasées","1 bonne pincée de flocons de piment (facultatif)","100 g de mini-épis de maïs, coupés en deux","3 oignons nouveaux, coupés en tronçons de 2 cm","1 c. à café bombée de poudre de cinq-épices chinoises","90 g de mini pak-choï, feuilles séparées en gardant le cœur intact","1 tomate fraîche, finement hachée","120 g de germes de soja","2 c. à café de sauce soja à teneur réduite en sel"],
["Faites cuire les nouilles selon les indications du paquet, généralement 2 à 4 minutes environ. Égouttez-les dans une passoire, rincez-les à l'eau froide pour arrêter la cuisson et réservez.","Chauffez l'huile dans un wok ou une grande poêle, ajoutez l'oignon et le poivron rouge et faites sauter 2 à 3 minutes. Ajoutez les champignons, l'ail et les flocons de piment, le cas échéant, et remuez encore 1 minute.","Ajoutez les mini-épis de maïs, les oignons nouveaux, la poudre de cinq-épices chinoises et le pak-choï, et continuez de remuer encore 2 à 3 minutes.","Ajoutez la tomate et les nouilles et mélangez bien 1 à 2 minutes, jusqu'à ce que les nouilles soient chaudes.","Incorporez les germes de soja et la sauce soja, laissez cuire encore 1 minute et servez."],
["Utilisez des nouilles de riz pour une version sans gluten.","Coupez les oignons nouveaux en biais pour une forme plus originale.","Lorsque vous préparez un sauté au wok, préparez d'abord tous vos ingrédients et gardez-les à portée de main pour les jeter dans le wok.",fv(2)]),
R(7944719,"Salade d'épinards, citron et feta","Une salade fraîche et savoureuse, parfaite pour une journée d'été.","3","117 g",
["250 g d'épinards frais","1 c. à soupe de pignons de pin","30 g de feta","zeste râpé et jus d'1 citron","1 c. à soupe d'huile d'olive extra vierge","poivre noir fraîchement moulu"],
["Lavez les épinards et mettez-les dans une casserole avec un couvercle. Faites-les cuire 2 à 3 minutes en remuant à deux reprises (inutile d'ajouter de l'huile ou de l'eau : l'eau du lavage qui reste sur les épinards suffit). Égouttez l'excès d'eau et laissez refroidir.","Pendant ce temps, faites griller les pignons de pin dans une poêle sèche en remuant régulièrement 1 à 2 minutes, jusqu'à ce qu'ils commencent juste à dorer, puis retirez-les de la poêle et réservez.","Pressez délicatement les épinards pour en extraire l'eau restante et répartissez-les sur un plat de service.","Émiettez la feta par-dessus, puis parsemez de pignons de pin grillés.","Saupoudrez de zeste de citron, puis arrosez de jus de citron et d'huile d'olive. Poivrez et servez."],
["Vous pouvez parsemer cette salade d'un peu de fromage de chèvre ou de copeaux de parmesan à la place de la feta. Ou utiliser des amandes effilées légèrement grillées ou des graines de tournesol à la place des pignons de pin.","Cette salade peut être préparée à l'avance, mais n'ajoutez le jus de citron et l'huile qu'au moment de servir.","Elle fonctionne aussi avec des épinards surgelés : il suffit de les décongeler et d'en presser l'excès d'eau, sans les cuire.",fv(1)]),
R(7945459,"Gado gado","Salade indonésienne de légumes cuits et crus avec une sauce épicée aux cacahuètes.","4","380 g",
["1 à 2 patates douces, épluchées et coupées en cubes","1 à 2 c. à café d'huile de colza","1 paquet de 300 g de tofu, coupé en cubes","300 g de germes de soja","1 grosse carotte, taillée en rubans à l'économe","1 poivron rouge, émincé","6 oignons nouveaux, hachés","10 cm de concombre, haché","160 g de chou, émincé","160 g de haricots verts fins, blanchis","Pour la sauce§1 c. à soupe de beurre de cacahuète croquant non salé","Pour la sauce§2 c. à café de sauce soja à teneur réduite en sel","Pour la sauce§2 c. à café de miel liquide","Pour la sauce§1 c. à café d'édulcorant en grains","Pour la sauce§1 petit piment rouge, finement haché","Pour la sauce§jus d'1 citron vert","Pour la sauce§1 c. à soupe d'eau"],
["Faites bouillir les patates douces. Laissez-les refroidir, puis réservez.","Pendant ce temps, mettez 1 c. à café d'huile dans une poêle et faites dorer le tofu de chaque côté, 4 à 5 minutes, jusqu'à ce qu'il soit croustillant, en ajoutant un peu d'huile si nécessaire.","Pendant la cuisson du tofu, mélangez tous les ingrédients de la sauce.","Répartissez les patates douces et les légumes sur 4 assiettes, parsemez de tofu et arrosez de sauce pour servir."],
["Pour blanchir les haricots, plongez-les 3 à 4 minutes dans l'eau bouillante, puis immergez-les aussitôt dans l'eau froide pour arrêter la cuisson.",fv(3)]),
R(7949087,"Nouilles au poulet","Un plat simple et rapide que les adultes comme les enfants adoreront. Envoyé par Debbie Southwell","4","360 g",
["300 g de nouilles aux œufs sèches","1 cube de bouillon de poulet à teneur réduite en sel, dissous dans 500 ml d'eau","6 c. à café de sauce soja foncée à teneur réduite en sel","100 g de petits pois surgelés","150 g de maïs en grains, poids égoutté","200 g de poulet cuit, effiloché","2 c. à café de fécule de maïs"],
["Faites cuire les nouilles selon les indications du paquet, égouttez-les et réservez.","Mettez le bouillon, la sauce soja, les petits pois, le maïs et le poulet dans une casserole à feu moyen. Portez à frémissement et laissez cuire 2 minutes.","Dans une petite tasse, délayez la fécule de maïs dans 4 c. à soupe d'eau froide, versez dans la casserole, puis remuez encore 1 minute, jusqu'à ce que le liquide épaississe légèrement.","Ajoutez les nouilles et réchauffez brièvement en remuant pour bien mélanger."],
["Vous pouvez ajouter de nombreux autres légumes à ce plat, comme des oignons nouveaux finement hachés, du poivron rouge, des champignons émincés ou du pak-choï.","Essayez d'ajouter 1 c. à café de poudre de cinq-épices chinoises ou quelques flocons de piment.","Utilisez des nouilles de riz pour une alternative sans gluten.",fv(0)]),
R(7950673,"Brochettes de poulet fumées","Un délicieux plat épicé, riche en protéines. Avec nos remerciements à la cheffe célèbre Sophie Grigson pour cette recette.","8","215 g",
[M+"2 c. à soupe de graines de coriandre grillées",M+"1 c. à soupe de graines de cumin grillées",M+"4 gousses d'ail, épluchées",M+"1 morceau de 4 cm de gingembre, grossièrement haché",M+"2 piments rouges, épépinés et grossièrement hachés",M+"poivre noir fraîchement moulu",M+"1 c. à soupe de concentré de tomates séchées",M+"3 c. à soupe de vinaigre de vin blanc",M+"3 c. à soupe d'huile d'olive extra vierge","Pour les brochettes§8 petits blancs de poulet (environ 1 kg), coupés en cubes de 2,5 à 3,5 cm","Pour les brochettes§4 courgettes moyennes, coupées en rondelles de 2 cm d'épaisseur","Pour les brochettes§8 quartiers de citron jaune ou vert, pour servir"],
["Pour préparer la marinade, moulez les graines de coriandre et de cumin en poudre.","Pilez l'ail, le gingembre et les piments avec une pincée de poivre dans un mortier, jusqu'à obtenir une pâte grossière.","Incorporez la coriandre et le cumin, le concentré de tomates, le vinaigre et l'huile d'olive. Ajoutez 2 c. à soupe d'eau et mélangez. Versez sur les morceaux de poulet et retournez-les pour bien les enrober.","Laissez mariner au moins une demi-heure (ou jusqu'à 24 heures, à couvert, au réfrigérateur).","Préchauffez bien le gril ou le barbecue. Enfilez les morceaux de poulet sur 8 longues brochettes ou 16 petites, en alternant avec les rondelles de courgette. Faites cuire au gril ou au barbecue environ 10 minutes, en retournant plusieurs fois, jusqu'à ce qu'ils soient dorés et bien cuits. Servez avec des quartiers de citron jaune ou vert, et du riz ou de la salade."],
["Si vous n'avez pas de pilon et mortier, mixez simplement les ingrédients de la marinade avec un mixeur plongeant ou un robot de cuisine.","Vous pouvez utiliser des cubes de saumon à la place du poulet, ou des cubes de tofu pour une version végétalienne.",fv(0)]),
R(7951025,"Mug au micro-ondes : saumon au sésame et brocoli","Une savoureuse gourmandise de style chinois en moins de 10 minutes. Peut être servie avec du riz ou des nouilles pour un repas copieux.","2","123 g",
["1 pavé de saumon sans peau ni arêtes, coupé en cubes (150 g)","1 c. à café d'huile de sésame grillé","½ c. à café de poudre de cinq-épices chinoises","70 g de brocoli, divisé en petits bouquets","2 oignons nouveaux, finement hachés"],
["Mettez le saumon dans un bol, ajoutez l'huile de sésame et les cinq-épices, et mélangez bien pour enrober le saumon.","Mettez un peu de brocoli et d'oignons nouveaux dans un mug, ajoutez un peu de saumon, puis encore du brocoli, en répartissant uniformément. Vous pouvez bien tasser, car le tout réduit un peu à la cuisson.","Ajoutez 2 c. à café d'eau, couvrez de film alimentaire et percez un trou sur le dessus.","Faites chauffer 2 minutes, laissez reposer 1 minute avant de retirer le film et de servir."],
["Essayez d'ajouter d'autres légumes, comme des pois gourmands ou de fines tranches de poivron.","Pour une touche tandoori, essayez de la poudre de curry à la place de la poudre de cinq-épices chinoises.",fv(0)]),
R(7953493,"Salade de lentilles aux herbes, vinaigrette à la tomate et au sumac","Lentilles du Puy avec un mélange de légumes cuits et crus, garnies de tomates fraîches, de sumac et d'herbes.","4","240 g",
["1 c. à café bombée de sumac et une pincée pour servir","1 bon tour de moulin de poivre","jus d'un demi-citron","1 c. à soupe d'huile d'olive extra vierge","20 g de persil frais, finement haché","15 g de menthe fraîche, finement hachée","1 boîte de 400 g de lentilles vertes égouttées (240 g)","1 grosse tomate, finement hachée (80 g)","1 poivron vert, finement haché","100 g de concombre, finement haché","1 oignon, finement haché (150 g)","1 cœur de laitue (little gem), feuilles extérieures retirées et cœur haché","12 tomates cerises, coupées en deux"],
["Mélangez le sumac, le poivre, le jus de citron, l'huile d'olive, le persil et la menthe pour préparer la vinaigrette, puis réservez.","Mélangez les lentilles, la tomate, le poivron vert, le concombre et l'oignon, puis incorporez la vinaigrette.","Placez la laitue hachée au centre d'un plat de service et les feuilles de laitue entières tout autour. Disposez le mélange de lentilles par-dessus, répartissez les tomates cerises sur le pourtour, saupoudrez d'une bonne pincée de sumac et servez."],
["Essayez d'adapter la recette avec vos légumes préférés : la plupart conviennent à cette salade.","La salade est encore plus délicieuse saupoudrée d'un peu de fromage de chèvre émietté.",fv(2)]),
R(7954392,"Cannellonis aux épinards et à la ricotta","Une version allégée en matières grasses de cannellonis farcis aux épinards, à la ricotta, aux poireaux et aux oignons, cuits au four dans une riche sauce tomate.","6","170 g",
["1 c. à café d'huile de colza","1 gros oignon, finement haché","1 poireau, finement haché","3 gousses d'ail, écrasées","250 g d'épinards en feuilles surgelés","150 g de ricotta","½ c. à café de noix de muscade","120 g de cannellonis (poids sec), cuits selon les indications du paquet et rafraîchis à l'eau froide","1 boîte de 400 g de tomates concassées","1 c. à café bombée d'origan","1 c. à soupe de concentré de tomates","1 bon tour de moulin de poivre noir","25 g de mozzarella, finement tranchée"],
["Préchauffez le four à 180 °C (th. 4). Versez l'huile dans une casserole et faites cuire l'oignon et le poireau 5 à 8 minutes. Incorporez l'ail, faites cuire ensemble 1 minute et retirez du feu.","Ajoutez les épinards, la ricotta et la muscade, et mélangez bien.","Pendant ce temps, mettez les tomates dans un bol et ajoutez l'origan, le concentré de tomates et le poivre. Mélangez pour obtenir la sauce.","Garnissez les cannellonis du mélange d'épinards et de ricotta.","Versez la moitié de la sauce tomate dans un plat allant au four. Disposez les cannellonis farcis par-dessus et ajoutez le reste de la sauce. Recouvrez de mozzarella et faites cuire au four 15 minutes."],
["Faire cuire les pâtes, les égoutter et les plonger aussitôt dans l'eau froide arrête la cuisson et évite qu'elles ne deviennent pâteuses.","Pour une alternative sans produits laitiers ou végétalienne, utilisez du tofu soyeux à la place de la ricotta et garnissez d'un peu d'alternative végétale au fromage, sans produits laitiers.",fv(2)]),
R(7958217,"Salade de tomates, olives, asperges et haricots","Les asperges britanniques sont imbattables pour leur saveur et leur fraîcheur.","4","234 g",
["10 tiges d'asperges, parées et coupées en deux","1 boîte de 400 g de haricots blancs cuits, rincés et égouttés","4 tomates moyennes, coupées en quartiers","40 g d'olives vertes en saumure, égouttées et tranchées","40 g de basilic frais","1 c. à café de zeste de citron finement râpé","1 c. à soupe d'huile d'olive","1 c. à soupe de vinaigre balsamique","2 c. à café de jus de citron"],
["Préchauffez un gril ou un barbecue à feu vif. Faites cuire les asperges 1 à 2 minutes de chaque côté, ou jusqu'à ce qu'elles soient tendres.","Mettez les asperges, les haricots blancs, les tomates, les olives vertes, le basilic frais et le zeste de citron dans un grand saladier.","Fouettez l'huile d'olive, le vinaigre balsamique et le jus de citron dans un petit pichet.","Arrosez la salade de vinaigrette, mélangez et servez."],
["Si vous n'aimez pas les olives, utilisez à la place des tomates séchées finement tranchées.","Cette salade est idéale pour un buffet d'été et/ou pour accompagner du thon frais ou du saumon.",fv(2)]),
]
save(7,recs)
